[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WellStream Platform — Integrated Energy Data Management</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

        :root {
            --navy-dark: #0D1B2A;
            --navy-mid: #1B2838;
            --navy-light: #243B53;
            --teal-primary: #00B4D8;
            --teal-secondary: #0077B6;
            --teal-glow: rgba(0, 180, 216, 0.3);
            --green-accent: #6CC24A;
            --text-primary: #FFFFFF;
            --text-secondary: #A8B8C8;
            --text-muted: #6B7D8E;
            --border-color: rgba(255, 255, 255, 0.08);
            --card-bg: rgba(255, 255, 255, 0.04);
            --card-border: rgba(255, 255, 255, 0.1);
        }

        html { scroll-behavior: smooth; }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            background: var(--navy-dark);
            color: var(--text-primary);
            line-height: 1.6;
            overflow-x: hidden;
        }

        a { color: inherit; text-decoration: none; }
        button { font-family: inherit; cursor: pointer; border: none; background: none; }

        /* Navigation */
        .nav {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            z-index: 1000;
            background: rgba(13, 27, 42, 0.95);
            backdrop-filter: blur(20px);
            border-bottom: 1px solid var(--border-color);
            padding: 0 24px;
        }

        .nav-container {
            max-width: 1400px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 72px;
        }

        .nav-brand {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 700;
            font-size: 22px;
            letter-spacing: -0.5px;
        }

        .nav-brand svg { width: 36px; height: 36px; }

        .nav-links {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .nav-dropdown {
            position: relative;
        }

        .nav-dropdown-trigger {
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 10px 16px;
            color: var(--text-secondary);
            font-size: 14px;
            font-weight: 500;
            border-radius: 8px;
            transition: all 0.2s ease;
        }

        .nav-dropdown-trigger:hover, .nav-dropdown-trigger.active {
            color: var(--text-primary);
            background: rgba(255,255,255,0.05);
        }

        .nav-dropdown-trigger svg { width: 16px; height: 16px; transition: transform 0.2s; }
        .nav-dropdown:hover .nav-dropdown-trigger svg { transform: rotate(180deg); }

        .nav-dropdown-menu {
            position: absolute;
            top: calc(100% + 8px);
            left: 0;
            background: var(--navy-mid);
            border: 1px solid var(--border-color);
            border-radius: 12px;
            padding: 8px;
            min-width: 220px;
            opacity: 0;
            visibility: hidden;
            transform: translateY(-8px);
            transition: all 0.2s ease;
            box-shadow: 0 20px 40px rgba(0,0,0,0.4);
        }

        .nav-dropdown:hover .nav-dropdown-menu {
            opacity: 1;
            visibility: visible;
            transform: translateY(0);
        }

        .nav-dropdown-item {
            display: block;
            padding: 12px 16px;
            border-radius: 8px;
            font-size: 14px;
            color: var(--text-secondary);
            transition: all 0.15s ease;
        }

        .nav-dropdown-item:hover {
            background: rgba(255,255,255,0.08);
            color: var(--text-primary);
        }

        .nav-dropdown-item small {
            display: block;
            font-size: 12px;
            color: var(--text-muted);
            margin-top: 2px;
        }

        .nav-cta {
            padding: 10px 20px;
            background: linear-gradient(135deg, var(--teal-primary), var(--teal-secondary));
            color: var(--navy-dark);
            font-size: 14px;
            font-weight: 600;
            border-radius: 8px;
            transition: all 0.2s ease;
        }

        .nav-cta:hover {
            transform: translateY(-1px);
            box-shadow: 0 8px 24px var(--teal-glow);
        }

        /* Mobile Nav */
        .nav-mobile-toggle {
            display: none;
            padding: 8px;
            color: var(--text-primary);
        }

        .nav-mobile-toggle svg { width: 24px; height: 24px; }

        @media (max-width: 768px) {
            .nav-links { display: none; }
            .nav-mobile-toggle { display: flex; }
            .nav-cta { display: none; }
        }

        /* Hero Section */
        .hero {
            min-height: 100vh;
            display: flex;
            align-items: center;
            padding: 120px 24px 80px;
            position: relative;
            overflow: hidden;
        }

        .hero::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: radial-gradient(ellipse at 30% 20%, rgba(0, 180, 216, 0.15) 0%, transparent 50%),
                        radial-gradient(ellipse at 80% 80%, rgba(0, 119, 182, 0.1) 0%, transparent 40%);
            pointer-events: none;
        }

        .hero-container {
            max-width: 1400px;
            margin: 0 auto;
            width: 100%;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            align-items: center;
        }

        .hero-content { position: relative; z-index: 1; }

        .hero-label {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 100px;
            font-size: 12px;
            font-weight: 600;
            color: var(--teal-primary);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 24px;
        }

        .hero-label::before {
            content: '';
            width: 8px;
            height: 8px;
            background: var(--green-accent);
            border-radius: 50%;
            animation: pulse 2s infinite;
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.5; }
        }

        .hero-title {
            font-size: clamp(40px, 5vw, 64px);
            font-weight: 800;
            line-height: 1.1;
            letter-spacing: -2px;
            margin-bottom: 24px;
        }

        .hero-title .highlight {
            background: linear-gradient(135deg, var(--teal-primary), var(--green-accent));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .hero-subtitle {
            font-size: 18px;
            color: var(--text-secondary);
            line-height: 1.7;
            margin-bottom: 40px;
            max-width: 540px;
        }

        .hero-actions {
            display: flex;
            gap: 16px;
            flex-wrap: wrap;
        }

        .btn-primary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 16px 32px;
            background: linear-gradient(135deg, var(--teal-primary), var(--teal-secondary));
            color: var(--navy-dark);
            font-size: 15px;
            font-weight: 600;
            border-radius: 10px;
            transition: all 0.2s ease;
        }

        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 12px 32px var(--teal-glow);
        }

        .btn-secondary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 16px 32px;
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            color: var(--text-primary);
            font-size: 15px;
            font-weight: 600;
            border-radius: 10px;
            transition: all 0.2s ease;
        }

        .btn-secondary:hover {
            background: rgba(255,255,255,0.08);
            border-color: rgba(255,255,255,0.2);
        }

        .btn-secondary svg { width: 18px; height: 18px; }

        /* Hero Visual */
        .hero-visual {
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .hero-diagram {
            position: relative;
            width: 100%;
            max-width: 500px;
        }

        .hero-diagram svg { width: 100%; height: auto; }

        /* Featured Product Banner */
        .featured-banner {
            background: linear-gradient(135deg, var(--navy-mid), var(--navy-light));
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: 32px 40px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 24px;
            margin-top: 60px;
        }

        .featured-badge {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .featured-badge-icon {
            width: 48px;
            height: 48px;
            background: linear-gradient(135deg, var(--teal-primary), var(--green-accent));
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .featured-badge-icon svg { width: 28px; height: 28px; color: var(--navy-dark); }

        .featured-info h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 4px;
        }

        .featured-info span {
            font-size: 13px;
            color: var(--teal-primary);
            font-weight: 600;
        }

        .btn-learn {
            padding: 12px 24px;
            background: rgba(0, 180, 216, 0.1);
            border: 1px solid var(--teal-primary);
            color: var(--teal-primary);
            font-size: 14px;
            font-weight: 600;
            border-radius: 8px;
            transition: all 0.2s ease;
        }

        .btn-learn:hover {
            background: rgba(0, 180, 216, 0.2);
        }

        @media (max-width: 768px) {
            .hero-container { grid-template-columns: 1fr; gap: 40px; }
            .hero-visual { order: -1; }
            .featured-banner { flex-direction: column; text-align: center; }
        }

        /* Use Cases Section */
        .use-cases {
            padding: 100px 24px;
            background: var(--navy-mid);
        }

        .section-container {
            max-width: 1400px;
            margin: 0 auto;
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
        }

        .section-label {
            font-size: 12px;
            font-weight: 700;
            color: var(--teal-primary);
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 16px;
        }

        .section-title {
            font-size: clamp(32px, 4vw, 48px);
            font-weight: 800;
            letter-spacing: -1px;
            margin-bottom: 20px;
        }

        .section-desc {
            font-size: 17px;
            color: var(--text-secondary);
            max-width: 700px;
            margin: 0 auto;
            line-height: 1.7;
        }

        /* Industry Tabs */
        .industry-tabs {
            display: flex;
            justify-content: center;
            gap: 8px;
            margin-bottom: 48px;
            flex-wrap: wrap;
        }

        .industry-tab {
            padding: 12px 24px;
            font-size: 14px;
            font-weight: 600;
            color: var(--text-muted);
            border-radius: 8px;
            transition: all 0.2s ease;
            border: 1px solid transparent;
        }

        .industry-tab:hover {
            color: var(--text-secondary);
            background: rgba(255,255,255,0.05);
        }

        .industry-tab.active {
            color: var(--teal-primary);
            background: rgba(0, 180, 216, 0.1);
            border-color: rgba(0, 180, 216, 0.3);
        }

        /* Use Case Grid */
        .use-case-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .use-case-card {
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 16px;
            padding: 32px;
            transition: all 0.3s ease;
            cursor: pointer;
        }

        .use-case-card:hover {
            background: rgba(255,255,255,0.06);
            border-color: rgba(0, 180, 216, 0.3);
            transform: translateY(-4px);
        }

        .use-case-icon {
            width: 56px;
            height: 56px;
            background: linear-gradient(135deg, rgba(0, 180, 216, 0.2), rgba(0, 119, 182, 0.1));
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
        }

        .use-case-icon svg { width: 28px; height: 28px; color: var(--teal-primary); }

        .use-case-card h3 {
            font-size: 18px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .use-case-card p {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        @media (max-width: 1024px) {
            .use-case-grid { grid-template-columns: repeat(2, 1fr); }
        }

        @media (max-width: 640px) {
            .use-case-grid { grid-template-columns: 1fr; }
        }

        /* Platform Overview Diagram */
        .platform-section {
            padding: 100px 24px;
            background: var(--navy-dark);
            position: relative;
        }

        .platform-diagram {
            max-width: 1000px;
            margin: 0 auto;
            position: relative;
        }

        .platform-svg {
            width: 100%;
            height: auto;
        }

        .platform-cards {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 32px;
            margin-top: 60px;
        }

        .platform-card {
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 16px;
            padding: 32px;
            text-align: center;
            transition: all 0.3s ease;
        }

        .platform-card:hover {
            border-color: var(--teal-primary);
            box-shadow: 0 0 40px rgba(0, 180, 216, 0.15);
        }

        .platform-card-icon {
            width: 72px;
            height: 72px;
            margin: 0 auto 24px;
            background: linear-gradient(135deg, rgba(0, 180, 216, 0.15), rgba(108, 194, 74, 0.1));
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .platform-card-icon svg { width: 36px; height: 36px; color: var(--teal-primary); }

        .platform-card h3 {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .platform-card p {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        @media (max-width: 768px) {
            .platform-cards { grid-template-columns: 1fr; }
        }

        /* Company Culture */
        .culture-section {
            padding: 100px 24px;
            background: linear-gradient(180deg, var(--navy-mid) 0%, var(--navy-dark) 100%);
        }

        .culture-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 80px;
            align-items: center;
        }

        .culture-text h2 {
            font-size: clamp(36px, 4vw, 48px);
            font-weight: 800;
            letter-spacing: -1px;
            margin-bottom: 24px;
        }

        .culture-text h2 span {
            color: var(--green-accent);
        }

        .culture-text p {
            font-size: 17px;
            color: var(--text-secondary);
            line-height: 1.8;
            margin-bottom: 32px;
        }

        .culture-stats {
            display: flex;
            gap: 48px;
        }

        .culture-stat {
            text-align: center;
        }

        .culture-stat strong {
            display: block;
            font-size: 48px;
            font-weight: 800;
            color: var(--teal-primary);
            line-height: 1;
        }

        .culture-stat span {
            font-size: 14px;
            color: var(--text-muted);
        }

        .culture-visual {
            position: relative;
        }

        .culture-visual-bg {
            position: absolute;
            inset: 0;
            background: radial-gradient(circle, rgba(108, 194, 74, 0.1) 0%, transparent 70%);
            border-radius: 24px;
        }

        .culture-visual-content {
            position: relative;
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 24px;
            padding: 48px;
            text-align: center;
        }

        .culture-visual-content svg {
            width: 120px;
            height: 120px;
            margin-bottom: 24px;
            color: var(--teal-primary);
        }

        .culture-visual-content h4 {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 8px;
        }

        .culture-visual-content p {
            color: var(--text-secondary);
        }

        @media (max-width: 768px) {
            .culture-content { grid-template-columns: 1fr; }
            .culture-stats { justify-content: center; }
        }

        /* Renewables CTA */
        .renewables-section {
            padding: 80px 24px;
            background: var(--navy-dark);
        }

        .renewables-card {
            max-width: 1000px;
            margin: 0 auto;
            background: linear-gradient(135deg, rgba(108, 194, 74, 0.1), rgba(0, 180, 216, 0.05));
            border: 1px solid rgba(108, 194, 74, 0.3);
            border-radius: 24px;
            padding: 64px;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .renewables-card::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, rgba(108, 194, 74, 0.05) 0%, transparent 50%);
            pointer-events: none;
        }

        .renewables-card h2 {
            font-size: 36px;
            font-weight: 800;
            margin-bottom: 16px;
            position: relative;
        }

        .renewables-card p {
            font-size: 17px;
            color: var(--text-secondary);
            max-width: 600px;
            margin: 0 auto 32px;
            position: relative;
        }

        /* Footer */
        .footer {
            background: var(--navy-mid);
            border-top: 1px solid var(--border-color);
            padding: 80px 24px 40px;
        }

        .footer-grid {
            max-width: 1400px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr repeat(3, 1fr);
            gap: 60px;
            margin-bottom: 60px;
        }

        .footer-brand {
            max-width: 300px;
        }

        .footer-brand .nav-brand {
            margin-bottom: 20px;
        }

        .footer-brand p {
            font-size: 14px;
            color: var(--text-muted);
            line-height: 1.7;
        }

        .footer-col h4 {
            font-size: 12px;
            font-weight: 700;
            color: var(--text-muted);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 20px;
        }

        .footer-col ul { list-style: none; }

        .footer-col li { margin-bottom: 12px; }

        .footer-col a {
            font-size: 14px;
            color: var(--text-secondary);
            transition: color 0.2s;
        }

        .footer-col a:hover { color: var(--teal-primary); }

        .footer-bottom {
            max-width: 1400px;
            margin: 0 auto;
            padding-top: 40px;
            border-top: 1px solid var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 20px;
        }

        .footer-bottom p {
            font-size: 13px;
            color: var(--text-muted);
        }

        .footer-links {
            display: flex;
            gap: 24px;
        }

        .footer-links a {
            font-size: 13px;
            color: var(--text-muted);
            transition: color 0.2s;
        }

        .footer-links a:hover { color: var(--text-secondary); }

        .footer-portals {
            display: flex;
            gap: 16px;
            margin-top: 24px;
        }

        .footer-portal {
            padding: 8px 16px;
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            border-radius: 6px;
            font-size: 12px;
            font-weight: 600;
            color: var(--text-secondary);
            transition: all 0.2s;
        }

        .footer-portal:hover {
            border-color: var(--teal-primary);
            color: var(--teal-primary);
        }

        @media (max-width: 1024px) {
            .footer-grid { grid-template-columns: repeat(2, 1fr); }
        }

        @media (max-width: 640px) {
            .footer-grid { grid-template-columns: 1fr; }
            .footer-bottom { flex-direction: column; text-align: center; }
        }

        /* Cookie Banner */
        .cookie-banner {
            position: fixed;
            bottom: 24px;
            left: 24px;
            right: 24px;
            max-width: 500px;
            background: var(--navy-light);
            border: 1px solid var(--border-color);
            border-radius: 16px;
            padding: 24px;
            z-index: 999;
            box-shadow: 0 20px 60px rgba(0,0,0,0.5);
            opacity: 0;
            transform: translateY(20px);
            visibility: hidden;
            transition: all 0.3s ease;
        }

        .cookie-banner.show {
            opacity: 1;
            transform: translateY(0);
            visibility: visible;
        }

        .cookie-banner h4 {
            font-size: 16px;
            font-weight: 700;
            margin-bottom: 8px;
        }

        .cookie-banner p {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 20px;
            line-height: 1.6;
        }

        .cookie-actions {
            display: flex;
            gap: 12px;
        }

        .cookie-btn {
            flex: 1;
            padding: 12px 20px;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 600;
            transition: all 0.2s;
        }

        .cookie-btn-decline {
            background: var(--card-bg);
            border: 1px solid var(--card-border);
            color: var(--text-secondary);
        }

        .cookie-btn-decline:hover {
            background: rgba(255,255,255,0.08);
        }

        .cookie-btn-accept {
            background: linear-gradient(135deg, var(--teal-primary), var(--teal-secondary));
            color: var(--navy-dark);
        }

        .cookie-btn-accept:hover {
            box-shadow: 0 8px 24px var(--teal-glow);
        }

        @media (max-width: 640px) {
            .cookie-banner { left: 16px; right: 16px; bottom: 16px; }
            .cookie-actions { flex-direction: column; }
        }
    </style>
</head>
<body>
    <!-- Navigation -->
    <nav class="nav">
        <div class="nav-container">
            <a href="index.html" class="nav-brand">
                <svg viewBox="0 0 36 36" fill="none">
                    <rect width="36" height="36" rx="8" fill="url(#brand-gradient)"/>
