    <!-- Cookie Banner -->
    <div class="cookie-banner" id="cookieBanner">
        <h4>We value your privacy</h4>
        <p>We use cookies to enhance your browsing experience, serve personalized content, and analyze our traffic. By clicking "Accept", you consent to our use of cookies.</p>
        <div class="cookie-actions">
            <button class="cookie-btn cookie-btn-decline" id="cookieDecline">Decline</button>
            <button class="cookie-btn cookie-btn-accept" id="cookieAccept">Accept</button>
        </div>
    </div>

    <script>
        // Industry Tabs
        document.querySelectorAll('.industry-tab').forEach(tab => {
            tab.addEventListener('click', function() {
                document.querySelectorAll('.industry-tab').forEach(t => t.classList.remove('active'));
                this.classList.add('active');
            });
        });

        // Cookie Banner
        const cookieBanner = document.getElementById('cookieBanner');
        const cookieDecline = document.getElementById('cookieDecline');
        const cookieAccept = document.getElementById('cookieAccept');

        // Show cookie banner after 2 seconds if not previously decided
        if (!localStorage.getItem('cookiePreference')) {
            setTimeout(() => {
                cookieBanner.classList.add('show');
            }, 2000);
        }

        cookieAccept.addEventListener('click', () => {
            localStorage.setItem('cookiePreference', 'accepted');
            cookieBanner.classList.remove('show');
        });

        cookieDecline.addEventListener('click', () => {
            localStorage.setItem('cookiePreference', 'declined');
            cookieBanner.classList.remove('show');
        });

        // Smooth scroll for anchor links
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function(e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    target.scrollIntoView({ behavior: 'smooth' });
                }
            });
        });

        // Add animation on scroll
        const observerOptions = {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        };

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
